using System;using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using DualSteam.UI;
public partial class App {
 bool removingSetup;TextBlock removalStatus;ProgressBar removalProgress;
 FrameworkElement RemovalOptions(){removalStatus=Text(RemovalService.Pending?"A previous removal did not finish. Complete it below, then create a fresh Second Steam setup. Recovery records are preserved.":!RemovalService.Available?"No verified Second Steam account record is available.":"Remove the managed second Windows account, Steam client, profile and setup data. Review the paths and back up local saves first.",13,"text.secondary");removalProgress=new ProgressBar{IsIndeterminate=true,Height=4,Visibility=Visibility.Collapsed,Margin=new Thickness(0,12,0,0)};Theme.Bind(removalProgress,Control.ForegroundProperty,"accent.default");var button=ActionButton(RemovalService.Pending?"Finish removing setup":"Remove Dual Steam setup",RemoveSetup);button.IsEnabled=RemovalService.Available;return Group(Text("REMOVE SETUP",12,"text.muted",true),removalStatus,removalProgress,button);}
 async void RemoveSetup(){
  if(busy||checkingUpdates){toast.Show("Wait for the current operation to finish.");return;}
  RemovalPlan plan;try{plan=RemovalService.Preview();}catch(Exception ex){AppDialog.Show(window,ex.Message,"Removal unavailable",MessageBoxButton.OK,MessageBoxImage.Information);return;}
  var dialog=new Window{Title="Remove Dual Steam setup",Owner=window,Width=640,Height=540,MinWidth=560,MinHeight=460,WindowStartupLocation=WindowStartupLocation.CenterOwner};Ui.Name(dialog,"Remove Dual Steam setup");Theme.Bind(dialog,Control.BackgroundProperty,"bg.window");Theme.Bind(dialog,Control.FontFamilyProperty,"Font.App");var body=Stack();body.Margin=new Thickness(24);Heading("Remove Dual Steam setup","Review the setup before permanently removing it.",body);
  body.Children.Add(Group(Text("Windows account: "+plan.User,14,"text.primary",true),Text("Second client and profile: "+plan.Root,13,"text.secondary"),Text("Windows-registered profile: "+(plan.RegisteredProfile??"Recovery record will be checked"),13,"text.secondary")));body.Children.Add(Text("Removes the second Windows account, its Steam client, local logins, saves, settings, import backups and setup credentials. Any games downloaded inside that second-client folder are also removed. Main Steam and shared libraries outside this folder are preserved.",13,"text.secondary"));body.Children.Add(Text("The portable manager and its source/release backups remain available. You can set up Second Steam again, or delete the extracted manager folder separately. Administrator approval is required. Quit Second Steam and its games first.",13,"text.secondary"));
  var consent=new CheckBox{Content="I have backed up the second profile's local saves and settings.",Margin=new Thickness(0,20,0,12)};Theme.Bind(consent,Control.ForegroundProperty,"text.primary");body.Children.Add(consent);var row=new WrapPanel();var confirm=Ui.Button("Remove setup",true,()=>{dialog.DialogResult=true;});confirm.IsEnabled=false;consent.Checked+=(s,e)=>confirm.IsEnabled=true;consent.Unchecked+=(s,e)=>confirm.IsEnabled=false;row.Children.Add(confirm);var cancel=Ui.Button("Cancel",false,()=>dialog.DialogResult=false);cancel.Margin=new Thickness(8,0,0,0);row.Children.Add(cancel);body.Children.Add(row);dialog.Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};if(dialog.ShowDialog()!=true)return;
  busy=removingSetup=true;content.IsEnabled=false;if(removalStatus!=null)removalStatus.Text="Removing the managed setup… Windows may ask for administrator approval. Keep this app open.";if(removalProgress!=null)removalProgress.Visibility=Visibility.Visible;try{await System.Threading.Tasks.Task.Run(()=>RemovalService.Remove(plan));if(startupAuthorized&&!String.IsNullOrEmpty(startupEnvelope))RuntimeAuthorization.Authorize(Engine.Home,startupEnvelope);Theme.Apply("Dark");settingsScan=null;selectedGame=selectedSettings="";ShowPage("Profiles");if(!exitAfterOperation)AppDialog.Show(window,"Second Steam's managed setup was removed. Main Steam and shared game libraries were preserved. The manager is ready for a new setup.","Setup removed",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){Engine.Log("Removal: "+ex);if(removalStatus!=null)removalStatus.Text="Removal did not finish. Recovery records were kept for retry.";if(!exitAfterOperation)AppDialog.Show(window,ex.Message,"Removal did not finish",MessageBoxButton.OK,MessageBoxImage.Warning);}finally{busy=removingSetup=false;content.IsEnabled=true;if(removalProgress!=null)removalProgress.Visibility=Visibility.Collapsed;}if(exitAfterOperation){exitAfterOperation=false;ExitManager();return;}await Refresh();
